/* [statement, true?, why] */
D.TF = [["Sound travels faster in water than in air.",true,"About four times faster."],["Lightning is hotter than the surface of the Sun.",true,"Around 30,000 °C versus about 5,500 °C."],["Humans have four lungs.",false,"We have two."],["An octopus has three hearts.",true,"Two pump blood to the gills, one to the body."],["Bats are blind.",false,"Bats can see; many also use echolocation."],["Venus is the hottest planet in the Solar System.",true,"Its thick atmosphere traps heat."],["Diamonds are made of carbon.",true,"Pure carbon in a crystal lattice."],["The Great Wall of China is visible from the Moon with the naked eye.",false,"It's far too narrow."],["Water expands when it freezes.",true,"That's why ice floats."],["Bananas are botanically berries.",true,"Strange but true."],["Strawberries are botanically berries.",false,"Botanically they're not."],["Light from the Sun takes about 8 minutes to reach Earth.",true,"About 8 minutes 20 seconds."],["Adults have more bones than babies.",false,"Babies have around 300; many fuse to make 206."],["Mount Everest is the tallest mountain measured from base to peak.",false,"Mauna Kea is taller from its base on the sea floor."],["Penguins live at the North Pole.",false,"Wild penguins live in the Southern Hemisphere."],["Sharks are mammals.",false,"They're fish."],["Dolphins are mammals.",true,"They breathe air and feed their young milk."],["A day on Venus is longer than its year.",true,"It spins extremely slowly."],["Antarctica is the driest continent.",true,"Parts haven't seen rain for millions of years."],["Copper conducts electricity better than silver.",false,"Silver is the best conductor."],["Arteries carry blood away from the heart.",true,"Veins bring it back."],["Mercury is the closest planet to the Sun.",true,"It's also the smallest planet."],["Saturn is less dense than water.",true,"Its average density is about 0.69 g/cm³."],["There is no gravity in space.",false,"Astronauts float because they are in free fall."],["Electrons are bigger than protons.",false,"Protons are far more massive."],["Spiders are insects.",false,"They're arachnids, with eight legs."],["Koalas are bears.",false,"They're marsupials."],["Tomatoes are botanically fruit.",true,"They develop from the flower and hold seeds."],["The chemical symbol for gold is Ag.",false,"It's Au; Ag is silver."],["Plants release oxygen during photosynthesis.",true,"It's a by-product of splitting water."],["Absolute zero is −273.15 °C.",true,"The lowest possible temperature."],["Sound can travel through a vacuum.",false,"It needs a medium such as air."],["A group of crows is called a murder.",true,"An old collective noun."],["Earth is closest to the Sun in July.",false,"It's closest in early January."],["The Moon gives off its own light.",false,"It reflects sunlight."],["Camels store water in their humps.",false,"The humps store fat."],["Ostriches bury their heads in the sand.",false,"A myth; they lower their heads to turn their eggs."],["Blood is blue inside your body.",false,"It's always red; darker when low in oxygen."],["Neptune was predicted by mathematics before it was seen.",true,"Its position was calculated in 1846."],["Pluto is classed as a dwarf planet.",true,"Reclassified in 2006."],["Helium is lighter than air.",true,"That's why helium balloons float."],["Humans only use 10% of their brains.",false,"Brain scans show activity throughout."],["Frogs are reptiles.",false,"They're amphibians."],["Light travels at about 300,000 km per second.",true,"Roughly 299,792 km/s."],["Water boils at a lower temperature at the top of a mountain.",true,"Lower air pressure."],["Diamond is the hardest natural mineral.",true,"10 on the Mohs scale."],["The liver is the largest organ of the human body.",false,"The skin is."],["Butterflies taste with their feet.",true,"They have taste receptors on their legs."],["Bees can see ultraviolet light.",true,"Many flowers have UV patterns."],["Jupiter is a rocky planet.",false,"It's a gas giant."],["Rust forms when iron reacts with oxygen and water.",true,"Iron oxide."],["About 71% of Earth's surface is covered by water.",true,"Mostly ocean."],["Whales are fish.",false,"They're mammals."],["The Sun is a star.",true,"A yellow dwarf star."],["Thunder happens before lightning.",false,"Lightning causes thunder."],["Hydrogen is the most abundant element in the universe.",true,"Roughly three-quarters of normal matter."],["Male seahorses give birth.",true,"The female lays eggs in the male's pouch."],["Antibiotics kill viruses.",false,"They work on bacteria."],["Mars has two moons.",true,"Phobos and Deimos."],["Venus spins in the opposite direction to most planets.",true,"The Sun rises in the west there."],["Humans and dinosaurs lived at the same time.",false,"Dinosaurs died out 66 million years earlier."],["Glass is made mainly from sand.",true,"Silica sand, melted at high temperature."],["The Earth's inner core is solid.",true,"Enormous pressure keeps it solid."],["Ice is denser than liquid water.",false,"That's why ice floats."],["A teaspoon of neutron star would weigh billions of tonnes.",true,"Neutron stars are incredibly dense."],["Goldfish have a three-second memory.",false,"They can remember things for months."],["Insects have six legs.",true,"Three pairs."],["Some metals are liquid at room temperature.",true,"Mercury, for example."],["Your fingernails are made of the same protein as hair.",true,"Keratin."],["Chameleons are mammals.",false,"They're reptiles."]];

